shell_commands:
node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const v1 = ajv.compile({type: 'object', properties: {location: {type: 'string'}}, required: ['location']});
v1({});
console.log('required error:', JSON.stringify(v1.errors, null, 2));
const v2 = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
v2({ssn: 123456789});
console.log('type error:', JSON.stringify(v2.errors, null, 2));
"

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
